ee:message.ee:set-payload:
%dw 2.0
output application/java
import * from dw::core::Strings
import * from dw::Runtime
var msg = (try(() -> payload.body.receiveMessage.xmlMsg)).result

---
if (!isBlank(msg)) do{
    var obj = replaceAll(replaceAll(replaceAll(msg, "&quot;", "\""), "&lt;", "<"), "&gt;", ">")
    var readObj = try(() -> read(obj, "application/xml"))
    ---
    if (readObj.success)
        {
            parsed: true,
            description: write(readObj.result, "application/xml")
        }
    else {
        parsed: false,
        description: {
            "Fault": {
                faultcode: "soap:Server",
                faultstring: readObj.error.message
            }
        }
    }
}
else {
    parsed: false,
    description: {
            "Fault": {
                faultcode: "soap:Server",
                faultstring: "Missing required element 'xmlMg'"
            }
        }
}

%dw 2.0
output application/json
---
payload  match {
    case obj if obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP is Object -> //MAPEO RESPUESTA SOLICITUD NIP 0002
{
    "body": {
        MensajeABD: {
            CabeceraMensaje: obj.MensajeABD.CabeceraMensaje,
            CuerpoMensaje: {
                RespuestaSolicitudNIP: {
                    RespuestaABD: obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP.RespuestaABD,
                    (NumeracionRechazada: obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP.NumeracionRechazada.*NumeracionRechazada map ((item, index) -> {
                        Numero: item.Numero,
                        CodigosRechazo: {
                        	CodigoRechazo: item.CodigosRechazo.*CodigoRechazo
                        }
                    })) if (!isEmpty(obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP.NumeracionRechazada))
                }
            }
        }
    },
    "attachments": vars.attachments
}
    case obj if obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP is Object -> // MAPEO RESPUESTA REENVIO NIP 0004
    { 
        body: {
          MensajeABD: {
            CabeceraMensaje: obj.MensajeABD.CabeceraMensaje,
            CuerpoMensaje: {
		        "RespuestaSolicitudReenvioNIP": {
                    "RespuestaABD": obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP.RespuestaABD,
			        ("CodigosRechazo": {
			            "CodigoRechazo": obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP.CodigosRechazo.*CodigoRechazo
			        }) if (!isEmpty(obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP.CodigosRechazo))
			    }
		    }
        }
    }, 
    attachments: vars.attachments
}
    case obj if obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion is Object -> //MAPEO REPLICA SOLICITUD PORTACION DONANTE 1002
{ 
    body: {
	  "MensajeABD": {
		"CabeceraMensaje": obj.MensajeABD.CabeceraMensaje,
		"CuerpoMensaje": {
		  "ReplicaSolicitudPortacion": {
			"NombreRazonSocialAbonado": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NombreRazonSocialAbonado,
			"TipoDocumentoIdentificacion": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacion,
			"DireccionAbonado": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DireccionAbonado,
			"IdentificacionAbonado": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionAbonado,
            ("FechaExpedicionIdentificacion": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacion) if (!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacion)),
			("TipoDocumentoIdentificacionRepresentanteLegal": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacionRepresentanteLegal) if(!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacionRepresentanteLegal)),
			("IdentificacionRepresentanteLegal": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionRepresentanteLegal) if(!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionRepresentanteLegal)),
			("FechaExpedicionIdentificacionRepresentanteLegal": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacionRepresentanteLegal) if(!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacionRepresentanteLegal)),
			"Donante": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.Donante,
			"TipoUsuario": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoUsuario,
			"TipoServicio": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoServicio,
			"SolicitudTerceros": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.SolicitudTerceros,
			"ListaNumeracionNip": {
			  "NumeracionNip": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.ListaNumeracionNip.*NumeracionNip map ((item, index) -> {
				"Numero": item.Numero,
				"FechaCreacionNIP": item.FechaCreacionNIP
			  }) 
			},
			"NRN": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NRN,
			("DocumentoID": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoID) if (!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoID)),
            ("DocumentoAT": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoAT) if(!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoAT)),
            ("DocumentoCC": obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoCC) if(!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoCC))
		  }
		}
	  }
	},
    attachments: vars.attachments
}
    case obj if obj.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante is Object -> //MAPEO RESPUESTA SOLICITUD DONANTE
{ 
    body: {
        MensajeABD: {
            CabeceraMensaje: obj.MensajeABD.CabeceraMensaje,
            CuerpoMensaje: {
                ReplicaRespuestaSolicitudPortacionDonante: {
                    RespuestaABD: obj.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante.RespuestaABD,
                    (ListaNumeracionRechazada: {
                        NumeracionRechazada: obj.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante.ListaNumeracionRechazada.*NumeracionRechazada map ((item, index) -> {
                        Numero: item.Numero,
                        CodigosRechazo: {
                            CodigoRechazo: item.CodigosRechazo.*CodigoRechazo
                        },
                        (DocumentoFC: item.DocumentoFC) if (!isEmpty(item.DocumentoFC)),
                        (DocumentoDC: item.DocumentoDC) if (!isEmpty(item.DocumentoDC)),
                        (DocumentoFR: item.DocumentoFR) if (!isEmpty(item.DocumentoFR)),
                        (DocumentoUO: item.DocumentoUO) if (!isEmpty(item.DocumentoUO)),
                        (DocumentoLD: item.DocumentoLD) if (!isEmpty(item.DocumentoLD)),
                        (DocumentoLS: item.DocumentoLS) if (!isEmpty(item.DocumentoLS)),
                        (DocumentoNA: item.DocumentoNA) if (!isEmpty(item.DocumentoNA)),
                        (DocumentoNI: item.DocumentoNI) if (!isEmpty(item.DocumentoNI)),
                        (DocumentoLA: item.DocumentoLA) if (!isEmpty(item.DocumentoLA))

                    })}) if (!isEmpty(obj.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante.ListaNumeracionRechazada))
                }
            }
        }
    }, 
    attachments: vars.attachments
}
    case obj if obj.MensajeABD.CuerpoMensaje.SolicitudDeProgramacionPortacion is Object -> { body: obj, attachments: vars.attachments} // 1005 !
    case obj if obj.MensajeABD.CuerpoMensaje.ConfirmacionProgramacionPortacion is Object -> { body: obj, attachments: vars.attachments} // 1007 !
    case obj if obj.MensajeABD.CuerpoMensaje.RespuestaSolicitudCancelacion is Object -> { body: obj, attachments: vars.attachments} // 2002 !
    case obj if obj.MensajeABD.CuerpoMensaje.RechazoPortacion is Object -> // MAPEO RESPUESTA RECHAZO PORTACION 9999
{ 
    body: {
        MensajeABD: {
            CabeceraMensaje: obj.MensajeABD.CabeceraMensaje,
            CuerpoMensaje: {
		        "RechazoPortacion": {
			        "NumeracionesRechazadas": {
			            "NumeracionRechazada": obj.MensajeABD.CuerpoMensaje.RechazoPortacion.NumeracionesRechazadas.*NumeracionRechazada map ((item, index) -> {
                            Numero: item.Numero,
                            CodigosRechazo: {
                                CodigoRechazo: item.CodigosRechazo.*CodigoRechazo
                            }
                        })
			        }
			    }
		    }
        }
    },
    attachments: vars.attachments
}
    case obj if obj.MensajeABD.CuerpoMensaje.ErrorDetectadoABD is Object -> // MAPEO RESPUESTA ERROR ABD 9998
{ 
    body: {
        MensajeABD: {
            CabeceraMensaje: obj.MensajeABD.CabeceraMensaje,
            CuerpoMensaje: {
		        "ErrorDetectadoABD": {
			        "CodigosRechazo": {
			            "CodigoRechazo": obj.MensajeABD.CuerpoMensaje.ErrorDetectadoABD.CodigosRechazo.*CodigoRechazo
			        },
			        "IdentificadorMensajeErroneo": obj.MensajeABD.CuerpoMensaje.ErrorDetectadoABD.IdentificadorMensajeErroneo
			    }
		    }
        }
    }, 
    attachments: vars.attachments
}
    else -> {}
}

%dw 2.0
output application/xml
ns por https://www.portabilidad.co/
---
{
	por#receiveMessageResponse: {
		por#receiveMessageReturn: "Not Implemented"
	}
}

%dw 2.0
output application/xml
ns por https://www.portabilidad.co/
